<main class="do580-shell"><section class="do580-profile-hero"><div class="do580-profile-photo"><?php if($d['photo_url']):?><img src="<?=e($d['photo_url'])?>" alt="<?=e($d['display_name'])?>"><?php else:?><?=e(mb_strtoupper(mb_substr($d['display_name'],0,1)))?><?php endif;?></div><div><div class="do580-badges"><?php if($d['verified']):?><span class="do580-badge verified">VERIFIED PROFILE</span><?php endif;?><?php if($d['online_status']==='available'):?><span class="do580-badge online">ONLINE NOW</span><?php endif;?></div><h1><?=e($d['display_name'])?></h1><p class="meta"><?=e($d['specialty_name']?:'Medical Doctor')?> · <?=max(0,(int)$d['experience_years'])?> years experience</p><p class="meta"><?=e($d['qualification']?:'Qualification details not added')?><?php if($d['registration_no']):?> · Reg. <?=e($d['registration_no'])?><?php endif;?></p><p class="meta"><?=e($d['organization_name']?:'Online / Independent practice')?></p><p>★ <?=number_format((float)$d['rating'],1)?> · <?=(int)$d['review_count']?> reviews · <?=(int)$d['total_consultations']?> consultations</p></div><div class="do580-pricebox"><small>Online consultation</small><strong><?=do580_money((float)$d['online_fee'])?></strong><p>Clinic visit: <?=do580_money((float)$d['clinic_fee'])?></p><a class="do580-btn primary" style="width:100%" href="/book-doctor.php?doctor=<?=$id?>">Book Appointment</a></div></section>
<div class="do580-main-grid"><div><section class="do580-panel"><h2>About doctor</h2><p style="line-height:1.75;color:#5f7185"><?=nl2br(e($d['bio']?:'Doctor profile biography has not been added yet.'))?></p><div class="do580-service-grid" style="grid-template-columns:repeat(3,1fr);margin-top:18px"><div class="do580-service-card"><i>◉</i><b>Video</b><span><?=$d['video_enabled']?'Available':'Not enabled'?></span></div><div class="do580-service-card"><i>☎</i><b>Audio</b><span><?=$d['audio_enabled']?'Available':'Not enabled'?></span></div><div class="do580-service-card"><i>✉</i><b>Chat</b><span><?=$d['chat_enabled']?'Available':'Not enabled'?></span></div></div></section><section class="do580-panel"><h2>Availability</h2><?php if(!$availability):?><p>Doctor has not published a weekly schedule yet.</p><?php else:?><table class="do580-table"><thead><tr><th>Day</th><th>Time</th><th>Mode</th></tr></thead><tbody><?php $days=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];foreach($availability as $a):?><tr><td><?=e($days[(int)$a['weekday']]??'Day')?></td><td><?=e(date('h:i A',strtotime($a['start_time'])))?> – <?=e(date('h:i A',strtotime($a['end_time'])))?></td><td><?=e(str_replace('_',' ',$a['consultation_mode']))?></td></tr><?php endforeach;?></tbody></table><?php endif;?></section><section class="do580-panel"><h2>Patient reviews</h2><?php foreach($reviews as $r):?><article style="padding:12px 0;border-bottom:1px solid #edf1f5"><b>★ <?=max(1,min(5,(int)$r['rating']))?>/5</b><p><?=e($r['review']?:'Rating submitted after consultation.')?></p><small><?=e($r['patient_name']?:'Patient')?> · <?=e(date('d M Y',strtotime($r['created_at'])))?></small></article><?php endforeach;?><?php if(!$reviews):?><p>No published reviews yet.</p><?php endif;?></section></div><aside><section class="do580-panel"><h3>Doctor details</h3><p><b>Specialty</b><br><?=e($d['specialty_name']?:'—')?></p><p><b>Languages</b><br><?=e($d['languages']?:'Not specified')?></p><p><b>Consultation duration</b><br><?=max(10,(int)$d['consultation_minutes'])?> minutes</p><p><b>Status</b><br><?=e(ucfirst($d['online_status']))?></p></section><div class="do580-clinical-note">Doctor profiles and credentials must be verified by platform administrators. For emergencies, use local emergency services rather than waiting for an online consultation.</div></aside></div></main>
